from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    line = [[False] * w for _ in range(h)]
    # Markers aligned on a row or column define a segment joining the outermost pair.
    for r in range(h):
        cols = [c for rr, c in ones if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                line[r][c] = True
    for c in range(w):
        rows = [r for r, cc in ones if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                line[r][c] = True
    for r in range(h):
        for c in range(w):
            if line[r][c]:
                out[r][c] = 1
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or seen[r][c]:
                continue
            q = [(r, c)]
            seen[r][c] = True
            comp = []
            hit = False
            while q:
                rr, cc = q.pop()
                comp.append((rr, cc))
                hit |= line[rr][cc]
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr,nc))
            if hit:
                for rr, cc in comp:
                    out[rr][cc] = 1
    return out

